<?php require_once dirname(__DIR__).'/lib.php';admin_required();$err='';if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$lt=token();$rt=token();$cols=['property_address','property_detail','floor_info','area_m2','use_type','deposit','monthly_rent','payment_day','rent_account','late_rate','handover_date','start_date','end_date','terms','special_terms','lessor_name','lessor_birth','lessor_phone','lessor_address','agent_name','agent_phone','lessee_name','lessee_birth','lessee_phone','lessee_address'];$v=[];foreach($cols as $k)$v[]=$_POST[$k]??'';$sql='INSERT INTO contracts('.implode(',',$cols).',lessor_token_hash,lessee_token_hash,token_expires_at,created_at,updated_at) VALUES('.rtrim(str_repeat('?,',count($cols)),',').',?,?,DATE_ADD(NOW(),INTERVAL ? DAY),NOW(),NOW())';$v[]=hash_token($lt);$v[]=hash_token($rt);$v[]=(int)cfg('security.token_days');$s=db()->prepare($sql);$s->execute($v);$id=(int)db()->lastInsertId();audit($id,'admin','created');$_SESSION['new_lessor_token']=$lt;$_SESSION['new_lessee_token']=$rt;header('Location:view.php?id='.$id);exit;}catch(Throwable $e){$err=$e->getMessage();}$today=date('Y-m-d');$end=date('Y-m-d',strtotime('+2 years'));?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/app.css"><title>새 계약</title></head><body><?php include '_top.php'?><main class="wrap"><h1>새 임대차계약서</h1><?php if($err):?><div class="alert err"><?=e($err)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><section class="card grid"><h2 class="full">부동산 표시</h2><label class="full">소재지<input name="property_address" value="수원시 팔달구 정조로810번길 7-15" required></label><label>상세·지번<input name="property_detail" value="(팔달로1가 7-1번지)"></label><label>층수<input name="floor_info" value="3층"></label><label>전용면적(㎡)<input type="number" step="0.01" name="area_m2" value="57.7"></label><label>용도<input name="use_type" value="주거공간">